class Solution {
    public int[] shortestToChar(String s,char c){
        int n=s.length(),previous=-n;
        int[] answer=new int[n];
        for(int i=0;i<n;i++){
            if(s.charAt(i)==c)previous=i;
            answer[i]=i-previous;
        }
        int next=2*n;
        for(int i=n-1;i>=0;i--){
            if(s.charAt(i)==c)next=i;
            answer[i]=Math.min(answer[i],next-i);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun shortestToChar(s:String,c:Char):IntArray{
        val n=s.length;
        var previous=-n;
        val answer=IntArray(n);
        for(i in 0 until n){
            if(s[i]==c)previous=i;
            answer[i]=i-previous
        };
        var next=2*n;
        for(i in n-1 downTo 0){
            if(s[i]==c)next=i;
            answer[i]=minOf(answer[i],next-i)
        };
        return answer
    }
}

